const tariffTemplateList = `-- name: TariffTemplateList :many
select id, company_id, name, description, is_default, payload, created_at, updated_at from tariff_templates
where company_id = $1
  and ($2 = '' or name ilike '%' || $2 || '%')
  and ($3::boolean is null or is_default = $3)
order by name
limit $5 offset $4
`

type TariffTemplateListParams struct {
	CompanyID    uuid.UUID
	NameContains interface{}
	IsDefault    *bool
	OffsetVal    int32
	LimitVal     int32
}

func (q *Queries) TariffTemplateList(ctx context.Context, arg TariffTemplateListParams) ([]TariffTemplate, error) {
	rows, err := q.db.Query(ctx, tariffTemplateList,
		arg.CompanyID,
		arg.NameContains,
		arg.IsDefault,
		arg.OffsetVal,
		arg.LimitVal,
	)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var items []TariffTemplate
	for rows.Next() {
		var i TariffTemplate
		if err := rows.Scan(
			&i.ID,
			&i.CompanyID,
			&i.Name,
			&i.Description,
			&i.IsDefault,
			&i.Payload,
			&i.CreatedAt,
			&i.UpdatedAt,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

